from AlgorithmImports import *
from decimal import Decimal


class IndependentDailyStrategies(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self._strategy_a_lot = 0
        self._strategy_b_lot = 0

        self._previous_spy_close = None
        self._previous_spy_sma = None
        self._previous_spy_sma_ready = False

        self._previous_aapl_close = None
        self._aapl_red_streak = 0

        self._lot_orders = {}

    def OnData(self, data):
        self._apply_split(data, self.spy, "A")
        self._apply_split(data, self.aapl, "B")

        has_spy = data.Bars.ContainsKey(self.spy)
        has_aapl = data.Bars.ContainsKey(self.aapl)

        if has_aapl:
            aapl_close = data.Bars[self.aapl].Close
            if self._previous_aapl_close is None:
                self._aapl_red_streak = 0
            elif aapl_close < self._previous_aapl_close:
                self._aapl_red_streak += 1
            else:
                self._aapl_red_streak = 0

        all_bars_present = all(data.Bars.ContainsKey(symbol) for symbol in self.symbols)

        if all_bars_present and self._rules_ready():
            spy_close = data.Bars[self.spy].Close
            aapl_close = data.Bars[self.aapl].Close

            spy_crosses_above_sma = (
                self._previous_spy_close <= self._previous_spy_sma
                and spy_close > self.spy_sma.Current.Value
            )
            spy_crosses_below_sma = (
                self._previous_spy_close >= self._previous_spy_sma
                and spy_close < self.spy_sma.Current.Value
            )

            # Sells are evaluated before buys.
            if self._strategy_a_lot > 0 and spy_crosses_below_sma:
                self._submit_lot_order("A", self.spy, -self._strategy_a_lot)

            if self._strategy_b_lot > 0 and self.aapl_rsi.Current.Value > Decimal("60"):
                self._submit_lot_order("B", self.aapl, -self._strategy_b_lot)

            if self._strategy_a_lot == 0 and spy_crosses_above_sma:
                quantity = int(
                    (self.Portfolio.TotalPortfolioValue * Decimal("0.40")) / spy_close
                )
                if quantity > 0:
                    self._submit_lot_order("A", self.spy, quantity)

            if (
                self._strategy_b_lot == 0
                and self._aapl_red_streak >= 3
                and self.Portfolio.Cash >= Decimal("20000")
            ):
                quantity = int(Decimal("20000") / aapl_close)
                if quantity > 0:
                    self._submit_lot_order("B", self.aapl, quantity)

        if has_spy:
            self._previous_spy_close = data.Bars[self.spy].Close
            self._previous_spy_sma = self.spy_sma.Current.Value
            self._previous_spy_sma_ready = self.spy_sma.IsReady

        if has_aapl:
            self._previous_aapl_close = data.Bars[self.aapl].Close

    def OnOrderEvent(self, order_event):
        order = self._lot_orders.get(order_event.OrderId)
        if order is None:
            return

        if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            order["filled"] += order_event.FillQuantity

        if order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
            self._change_lot(
                order["slot"],
                -(order["quantity"] - order["filled"])
            )
            self._lot_orders.pop(order_event.OrderId, None)
        elif order_event.Status == OrderStatus.Filled:
            self._lot_orders.pop(order_event.OrderId, None)

    def _rules_ready(self):
        return (
            self.spy_sma.IsReady
            and self.aapl_rsi.IsReady
            and self._previous_spy_sma_ready
            and self._previous_spy_close is not None
            and self._previous_aapl_close is not None
        )

    def _submit_lot_order(self, slot, symbol, quantity):
        ticket = self.MarketOrder(symbol, quantity, tag=f"Strategy {slot}")

        if ticket is None or ticket.Status in (
            OrderStatus.Invalid,
            OrderStatus.Canceled
        ):
            return

        self._change_lot(slot, quantity)

        if ticket.Status != OrderStatus.Filled:
            self._lot_orders[ticket.OrderId] = {
                "slot": slot,
                "quantity": quantity,
                "filled": 0
            }

    def _change_lot(self, slot, quantity):
        if slot == "A":
            self._strategy_a_lot = max(0, self._strategy_a_lot + quantity)
        else:
            self._strategy_b_lot = max(0, self._strategy_b_lot + quantity)

    def _apply_split(self, data, symbol, slot):
        if not data.Splits.ContainsKey(symbol):
            return

        split = data.Splits[symbol]
        if split.Type != SplitType.SplitOccurred or split.SplitFactor == 0:
            return

        factor = float(split.SplitFactor)

        if slot == "A":
            self._strategy_a_lot = int(round(self._strategy_a_lot / factor))
        else:
            self._strategy_b_lot = int(round(self._strategy_b_lot / factor))

        for order in self._lot_orders.values():
            if order["slot"] == slot:
                order["quantity"] = int(round(order["quantity"] / factor))
                order["filled"] = int(round(order["filled"] / factor))

