        if data.Bars.ContainsKey(self.spy):
            self.spy_yesterday_close = self.spy_last_close
            self.spy_yesterday_sma = self.spy_last_sma
            self.spy_last_close = float(data.Bars[self.spy].Close)
            self.spy_last_sma = float(self.spy_sma.Current.Value)

        if data.Bars.ContainsKey(self.aapl):
            close = float(data.Bars[self.aapl].Close)

            if self.aapl_last_close is not None:
                if close < self.aapl_last_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_last_close = close
            self.aapl_close_count += 1

    def _rules_are_ready(self):
        return (
            self.spy_sma.IsReady
            and self.aapl_rsi.IsReady
            and self.spy_yesterday_close is not None
            and self.spy_yesterday_sma is not None
            and self.aapl_close_count >= 4
        )

    def _spy_crosses_above_sma(self):
        return (
            self.spy_yesterday_close <= self.spy_yesterday_sma
            and self.spy_last_close > self.spy_last_sma
        )

    def _spy_crosses_below_sma(self):
        return (
            self.spy_yesterday_close >= self.spy_yesterday_sma
            and self.spy_last_close < self.spy_last_sma
        )

