from AlgorithmImports import *


class IndependentDailyStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)
        self.SetWarmUp(101, Resolution.Daily)

        self.spy = self.AddEquity("SPY", Resolution.Daily, Market.USA, False).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily, Market.USA, False).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily, Market.USA, False).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily, Market.USA, False).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily, Market.USA, False).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_closes = RollingWindow[float](2)
        self.spy_sma_values = RollingWindow[float](2)

        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data):
        self._update_market_state(data)

        if self.IsWarmingUp:
            return

        for symbol in self.symbols:
            if not data.Bars.ContainsKey(symbol):
                return

        if not self._rules_ready():
            return

        spy_close = float(data.Bars[self.spy].Close)

        crossed_above_sma = (
            self.spy_closes[1] <= self.spy_sma_values[1]
            and self.spy_closes[0] > self.spy_sma_values[0]
        )
        crossed_below_sma = (
            self.spy_closes[1] >= self.spy_sma_values[1]
            and self.spy_closes[0] < self.spy_sma_values[0]
        )

        if self.strategy_a_lot > 0 and crossed_below_sma:
            self.MarketOrder(self.spy, -self.strategy_a_lot, "Strategy A sell")
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_lot, "Strategy B sell")
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and crossed_above_sma and spy_close > 0:
            quantity = int(
                float(self.Portfolio.TotalPortfolioValue) * 0.40 / spy_close
            )
            if quantity > 0:
                self.MarketOrder(self.spy, quantity, "Strategy A buy")
                self.strategy_a_lot = quantity

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            aapl_close = float(data.Bars[self.aapl].Close)
            available_cash = float(self.Portfolio.CashBook["USD"].Amount)
            quantity = int(20_000 / aapl_close) if aapl_close > 0 else 0

            if available_cash >= 20_000 and quantity > 0:
                self.MarketOrder(self.aapl, quantity, "Strategy B buy")
                self.strategy_b_lot = quantity

    def _update_market_state(self, data):
        if data.Bars.ContainsKey(self.spy):
            spy_bar = data.Bars[self.spy]
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
            self.spy_closes.Add(float(spy_bar.Close))

            if self.spy_sma.IsReady:
                self.spy_sma_values.Add(float(self.spy_sma.Current.Value))

        if data.Bars.ContainsKey(self.aapl):
            aapl_bar = data.Bars[self.aapl]
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

            if self.aapl_previous_close is not None:
                if aapl_bar.Close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_previous_close = aapl_bar.Close

    def _rules_ready(self):
        return (
            self.spy_sma.IsReady
            and self.aapl_rsi.IsReady
            and self.spy_closes.Count == 2
            and self.spy_sma_values.Count == 2
            and self.aapl_previous_close is not None
        )

