        self._ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self._bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self._aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self._symbols = [self._spy, self._aapl, self._ibm, self._bac, self._aig]

        self._spy_sma = self.SMA(self._spy, 100, Resolution.Daily)
        self._aapl_rsi = self.RSI(self._aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self._strategy_a_lot = 0
        self._strategy_b_lot = 0

        self._previous_spy_close = None
        self._previous_spy_sma = None
        self._previous_aapl_close = None
        self._aapl_red_streak = 0

    def OnData(self, data: Slice):
        if data.Bars.ContainsKey(self._aapl):
            aapl_close = data.Bars[self._aapl].Close

            if self._previous_aapl_close is not None:
                if aapl_close < self._previous_aapl_close:
                    self._aapl_red_streak += 1
                else:
                    self._aapl_red_streak = 0

            self._previous_aapl_close = aapl_close

        has_all_bars = all(data.Bars.ContainsKey(symbol) for symbol in self._symbols)

        if has_all_bars and self._spy_sma.IsReady and self._aapl_rsi.IsReady:
            spy_bar = data.Bars[self._spy]
            aapl_bar = data.Bars[self._aapl]

            if not self._has_open_order(self._spy):
                if (
                    self._strategy_a_lot > 0
                    and self._previous_spy_close is not None
                    and self._previous_spy_sma is not None
                    and self._previous_spy_close >= self._previous_spy_sma
                    and spy_bar.Close < self._spy_sma.Current.Value
                ):
                    self.MarketOrder(self._spy, -self._strategy_a_lot, "Strategy A sell")

            if not self._has_open_order(self._aapl):
                if self._strategy_b_lot > 0 and self._aapl_rsi.Current.Value > 60:
                    self.MarketOrder(self._aapl, -self._strategy_b_lot, "Strategy B sell")

            if not self._has_open_order(self._spy):
                if (
                    self._strategy_a_lot == 0
                    and self._previous_spy_close is not None
                    and self._previous_spy_sma is not None
                    and self._previous_spy_close <= self._previous_spy_sma
                    and spy_bar.Close > self._spy_sma.Current.Value
                ):
                    quantity = int((self.Portfolio.TotalPortfolioValue * 0.40) / spy_bar.Close)
                    if quantity > 0:
                        self.MarketOrder(self._spy, quantity, "Strategy A buy")

            if not self._has_open_order(self._aapl):
                if (
                    self._strategy_b_lot == 0
                    and self._aapl_red_streak >= 3
                    and self.Portfolio.Cash >= 20_000
                ):
                    quantity = int(20_000 / aapl_bar.Close)
                    if quantity > 0:
                        self.MarketOrder(self._aapl, quantity, "Strategy B buy")

        if data.Bars.ContainsKey(self._spy) and self._spy_sma.IsReady:
            self._previous_spy_close = data.Bars[self._spy].Close
            self._previous_spy_sma = self._spy_sma.Current.Value

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.FillQuantity == 0:
            return

        if order_event.Symbol == self._spy:
            self._strategy_a_lot += order_event.FillQuantity
        elif order_event.Symbol == self._aapl:
            self._strategy_b_lot += order_event.FillQuantity

    def _has_open_order(self, symbol: Symbol) -> bool:
        return len(self.Transactions.GetOpenOrders(symbol)) > 0

