            self._spy_today_sma = (
                self.spy_sma.Current.Value if self.spy_sma.IsReady else None
            )
            self._spy_last_close = bar.Close

        if data.Bars.ContainsKey(self.aapl):
            bar = data.Bars[self.aapl]

            if self._aapl_last_close is None:
                self._aapl_red_streak = 0
            elif bar.Close < self._aapl_last_close:
                self._aapl_red_streak += 1
            else:
                self._aapl_red_streak = 0

            self._aapl_last_close = bar.Close
            self._aapl_close_count += 1
            self.aapl_rsi.Update(bar.EndTime, bar.Close)

    def _rules_ready(self):
        return (
            self.spy_sma.IsReady
            and self.aapl_rsi.IsReady
            and self._spy_yesterday_close is not None
            and self._spy_yesterday_sma is not None
            and self._spy_today_sma is not None
            and self._aapl_close_count >= 4
        )

    def _spy_crosses_above_sma(self):
        return (
            self._spy_yesterday_close <= self._spy_yesterday_sma
            and self._spy_today_close > self._spy_today_sma
        )

    def _spy_crosses_below_sma(self):
        return (
            self._spy_yesterday_close >= self._spy_yesterday_sma
            and self._spy_today_close < self._spy_today_sma
        )

