from AlgorithmImports import *


class IndependentTwoSlotStrategies(QCAlgorithm):
    def Initialize(self) -> None:
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.SetWarmUp(101, Resolution.Daily)

        self.lots = {"A": 0, "B": 0}
        self.pending_orders = {"A": None, "B": None}
        self.order_strategies = {}

        self.spy_closes = []
        self.spy_sma_values = []

        self.previous_aapl_close = None
        self.aapl_red_streak = 0

    def OnData(self, data: Slice) -> None:
        self._update_market_state(data)

        if self.IsWarmingUp:
            return

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        if not self._rules_are_ready():
            return

        spy_close = float(data.Bars[self.spy].Close)
        aapl_close = float(data.Bars[self.aapl].Close)

        # Evaluate all sells before any buys.
        if (
            self.lots["A"] > 0
            and self.pending_orders["A"] is None
            and self._spy_crosses_below_sma()
        ):
            self._submit_order("A", self.spy, -self.lots["A"], "Strategy A sell")

        if (
            self.lots["B"] > 0
            and self.pending_orders["B"] is None
            and float(self.aapl_rsi.Current.Value) > 60
        ):
            self._submit_order("B", self.aapl, -self.lots["B"], "Strategy B sell")

        if (
            self.lots["A"] == 0
            and self.pending_orders["A"] is None
            and self._spy_crosses_above_sma()
        ):
            quantity = int(
                (0.40 * float(self.Portfolio.TotalPortfolioValue)) / spy_close
            )
            if quantity > 0:
                self._submit_order("A", self.spy, quantity, "Strategy A buy")

        if (
            self.lots["B"] == 0
            and self.pending_orders["B"] is None
            and self.aapl_red_streak >= 3
            and float(self.Portfolio.Cash) >= 20_000
        ):
            quantity = int(20_000 / aapl_close)
            if quantity > 0:
                self._submit_order("B", self.aapl, quantity, "Strategy B buy")

    def OnOrderEvent(self, order_event: OrderEvent) -> None:
        strategy = self.order_strategies.get(order_event.OrderId)
        if strategy is None:
            return

        if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            self.lots[strategy] = max(
                0, self.lots[strategy] + int(order_event.FillQuantity)
            )

        if order_event.Status in (
            OrderStatus.Filled,
